const getPersonalSpendingByCategory = `-- name: GetPersonalSpendingByCategory :many
SELECT
    COALESCE(c.name, 'Unclassified') AS category_name,
    mt.category_id,
    COALESCE(SUM(mt.amount_minor), 0)::bigint AS total_minor
FROM money_transactions mt
LEFT JOIN categories c ON c.id = mt.category_id AND c.workspace_id = mt.workspace_id
WHERE mt.workspace_id = $1
  AND mt.direction = 'money_out'
  AND mt.status = 'posted'
  AND mt.is_void = false
  AND mt.currency = $2
  AND mt.effective_date >= $3::date
  AND mt.effective_date <= $4::date
  AND mt.purpose NOT IN (
      'transfer', 'owner_transfer', 'opening_balance',
      'loan_principal', 'loan_lent', 'loan_repayment',
      'investment_purchase', 'investment_contribution', 'asset_acquisition'
  )
GROUP BY c.name, mt.category_id
ORDER BY total_minor DESC
`

type GetPersonalSpendingByCategoryParams struct {
	WorkspaceID int64       `json:"workspace_id"`
	Currency    string      `json:"currency"`
	FromDate    pgtype.Date `json:"from_date"`
	ToDate      pgtype.Date `json:"to_date"`
}

type GetPersonalSpendingByCategoryRow struct {
	CategoryName string      `json:"category_name"`
	CategoryID   pgtype.Int8 `json:"category_id"`
	TotalMinor   int64       `json:"total_minor"`
}

func (q *Queries) GetPersonalSpendingByCategory(ctx context.Context, arg GetPersonalSpendingByCategoryParams) ([]GetPersonalSpendingByCategoryRow, error) {
	rows, err := q.db.Query(ctx, getPersonalSpendingByCategory,
		arg.WorkspaceID,
		arg.Currency,
		arg.FromDate,
		arg.ToDate,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []GetPersonalSpendingByCategoryRow{}
	for rows.Next() {
		var i GetPersonalSpendingByCategoryRow
		if err := rows.Scan(&i.CategoryName, &i.CategoryID, &i.TotalMinor); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

