const listPersonalActivity = `-- name: ListPersonalActivity :many
SELECT
    mt.id,
    mt.workspace_id,
    mt.direction,
    mt.status,
    mt.amount_minor,
    mt.currency,
    mt.currency_exponent,
    mt.effective_date,
    mt.money_account_id,
    ma.name AS account_name,
    mt.destination_account_id,
    da.name AS destination_account_name,
    mt.category_id,
    c.name AS category_name,
    mt.counterparty_name,
    mt.purpose,
    mt.notes,
    mt.reference,
    mt.tags,
    mt.created_at,
    (SELECT COUNT(*)::bigint FROM attachments_metadata am WHERE am.workspace_id = mt.workspace_id AND am.transaction_id = mt.id) AS attachment_count
FROM money_transactions mt
LEFT JOIN money_accounts ma ON ma.id = mt.money_account_id AND ma.workspace_id = mt.workspace_id
LEFT JOIN money_accounts da ON da.id = mt.destination_account_id AND da.workspace_id = mt.workspace_id
LEFT JOIN categories c ON c.id = mt.category_id AND c.workspace_id = mt.workspace_id
WHERE mt.workspace_id = $1
  AND mt.effective_date >= $3::date
  AND mt.effective_date <= $4::date
  AND (
      $5::date IS NULL
      OR (mt.effective_date, mt.id) < ($5::date, $6::bigint)
  )
  AND (
      $7::text IS NULL
      OR $7::text = 'all'
      OR ($7::text = 'income' AND mt.direction = 'money_in' AND mt.purpose NOT IN ('transfer', 'owner_transfer', 'opening_balance', 'loan_borrowed', 'loan_collection', 'investment_disposal', 'asset_disposal'))
      OR ($7::text = 'expenses' AND mt.direction = 'money_out' AND mt.purpose NOT IN ('transfer', 'owner_transfer', 'opening_balance', 'loan_lent', 'loan_repayment', 'investment_purchase', 'investment_contribution', 'asset_acquisition'))
      OR ($7::text = 'transfers' AND (mt.direction = 'transfer' OR mt.purpose IN ('transfer', 'owner_transfer')))
      OR ($7::text = 'loans' AND mt.purpose IN ('loan_borrowed', 'loan_lent', 'loan_repayment', 'loan_collection', 'loan_principal'))
      OR ($7::text = 'investments' AND mt.purpose IN ('investment_purchase', 'investment_contribution', 'investment_income', 'investment_disposal'))
      OR ($7::text = 'assets' AND mt.purpose IN ('asset_acquisition', 'asset_disposal'))
  )
ORDER BY mt.effective_date DESC, mt.id DESC
LIMIT $2
`

